<script setup lang="ts">
import { Save, LoaderCircle, Cpu, Database, HardDrive, Cloud, Check, CircleAlert, RefreshCw, Info, AudioLines } from '@lucide/vue'
import type { Settings, Health } from '~/types'
const { data, error, refresh } = await useFetch<Settings>('/api/settings', { key: 'settings', timeout: 8000 })
const { data: health, refresh: refreshHealth } = await useFetch<Health>('/api/health', { key: 'health', timeout: 7000, server: false })
const { data: storageInfo, refresh: refreshStorage } = await useFetch<{ bucket: string; stored_bytes: number; buffer_bytes: number; disk_free_bytes: number; disk_total_bytes: number }>('/api/storage', { key: 'storage', timeout: 8000 })
const form = reactive<Settings>({ max_recordings: 4, max_exports: 2, buffer_seconds: 300, scratch_budget_gb: 20, min_free_disk_gb: 2, offline_poll_seconds: 90, retention_days: 0 })
watch(data, value => { if (value) Object.assign(form, value) }, { immediate: true })
const { toast } = useToast()
const busy = ref(false)
const saveError = ref('')
async function save() {
  busy.value = true
  saveError.value = ''
  try { await api('/settings', { method: 'PUT', body: form }); toast('Einstellungen gespeichert. Der Worker übernimmt sie automatisch.'); await refresh() }
  catch (e) { saveError.value = errorMessage(e) }
  finally { busy.value = false }
}
async function checkConnections() { await Promise.all([refreshHealth(), refreshStorage(), refresh()]) }
</script>
<template>
  <div>
    <div class="mb-8"><p class="eyebrow mb-2">Make It Yours</p><h1 class="page-title">Dein Studio, deine Regeln<span class="text-lime-300">.</span></h1><p class="mt-2 text-sm text-studio-400">Ressourcen verteilen, Puffer abstimmen und Speicher im Blick behalten.</p></div>
    <ConnectionError v-if="error" @retry="checkConnections" />
    <div v-else class="grid items-start gap-6 xl:grid-cols-[1fr_320px]">
      <form class="space-y-6" @submit.prevent="save">
        <section class="panel"><div class="flex items-center gap-3 border-b divider px-6 py-5"><Cpu :size="19" class="text-lime-300" /><div><h2 class="text-sm font-semibold">Aufnahme & Verarbeitung</h2><p class="mt-1 text-xs text-studio-400">Verteile die Leistung deines Workers.</p></div></div><div class="grid gap-6 p-6 sm:grid-cols-2"><div><label for="max-recordings" class="label">Gleichzeitige Aufnahmen</label><input id="max-recordings" v-model.number="form.max_recordings" class="input" type="number" min="1" max="50" required /><p class="hint">Weitere Kanäle warten auf einen freien Platz. Höhere Priorität wird zuerst berücksichtigt.</p></div><div><label for="max-exports" class="label">Parallele Clip-Exporte</label><input id="max-exports" v-model.number="form.max_exports" class="input" type="number" min="1" max="8" required /><p class="hint">Schnitt und Upload teilen sich diese Plätze. Pro Schnitt werden zwei Encoder-Threads verwendet.</p></div><div><label for="offline-poll" class="label">Offline-Kanäle prüfen · Sekunden</label><input id="offline-poll" v-model.number="form.offline_poll_seconds" class="input" type="number" min="30" max="1800" required /><p class="hint">Streamlink prüft die Erreichbarkeit; Wiederholungen werden zeitlich leicht versetzt.</p></div></div></section>
        <section class="panel"><div class="flex items-center gap-3 border-b divider px-6 py-5"><HardDrive :size="19" class="text-lime-300" /><div><h2 class="text-sm font-semibold">Lokaler Videopuffer</h2><p class="mt-1 text-xs text-studio-400">Schneller Zwischenspeicher für den richtigen Ausschnitt.</p></div></div><div class="grid gap-6 p-6 sm:grid-cols-2"><div><label for="buffer-seconds" class="label">Pufferlänge pro Kanal · Sekunden</label><input id="buffer-seconds" v-model.number="form.buffer_seconds" class="input" type="number" min="180" max="1800" step="1" required /><p class="hint">{{ (form.buffer_seconds / 60).toFixed(1) }} Minuten. Für offene Clip-Aufträge benötigte Segmente werden länger vorgehalten.</p></div><div><label for="scratch-budget" class="label">Arbeitsverzeichnis-Budget · GiB</label><input id="scratch-budget" v-model.number="form.scratch_budget_gb" class="input" type="number" min="2" max="2000" required /><p class="hint">Bei Überschreitung pausieren Aufnahmen. Offene Exporte werden weiter verarbeitet.</p></div><div><label for="disk-free" class="label">Freier Speicher als Reserve · GiB</label><input id="disk-free" v-model.number="form.min_free_disk_gb" class="input" type="number" min="1" max="500" required /></div></div></section>
        <section class="panel"><div class="flex items-center gap-3 border-b divider px-6 py-5"><Cloud :size="19" class="text-lime-300" /><div><h2 class="text-sm font-semibold">Clip-Aufbewahrung in S3</h2><p class="mt-1 text-xs text-studio-400">Private Dateien, zeitlich begrenzte Vorschau-Links.</p></div></div><div class="p-6"><label for="retention" class="label">Automatisch löschen nach · Tagen</label><input id="retention" v-model.number="form.retention_days" class="input max-w-xs" type="number" min="0" max="365" required /><p class="hint">0 = dauerhaft behalten. Favorisierte Clips werden von der automatischen Löschung ausgenommen.</p><p v-if="form.retention_days > 0" class="mt-4 flex gap-2 rounded-lg bg-amber-300/5 p-3 text-xs leading-relaxed text-amber-200"><CircleAlert :size="15" class="shrink-0" />Nicht favorisierte Clips, die älter als {{ form.retention_days }} Tage sind, werden samt S3-Dateien gelöscht.</p></div></section>
        <p v-if="saveError" role="alert" class="rounded-lg bg-red-400/10 p-4 text-sm text-red-300">{{ saveError }}</p><div class="flex items-center justify-between gap-4"><span class="text-[11px] text-studio-400">Änderungen gelten für den gesamten Worker.</span><button class="btn btn-primary" :disabled="busy"><LoaderCircle v-if="busy" class="animate-spin" :size="16" /><Save v-else :size="16" />Speichern</button></div>
      </form>
      <div class="space-y-5"><section class="panel p-5"><div class="mb-5 flex items-center justify-between"><h2 class="text-sm font-semibold">Verbindungen</h2><button class="icon-btn" aria-label="Verbindungen prüfen" @click="checkConnections"><RefreshCw :size="14" /></button></div><div class="space-y-4"><div v-for="service in [{ key: 'database' as const, label: 'PostgreSQL', sub: 'Metadaten & Aufträge', icon: Database }, { key: 'storage' as const, label: 'S3 Bucket', sub: health?.bucket || 'Dateispeicher', icon: Cloud }, { key: 'worker' as const, label: 'Capture Worker', sub: 'Streamlink + FFmpeg', icon: Cpu }]" :key="service.key" class="flex items-center gap-3"><span class="flex size-9 items-center justify-center rounded-lg bg-studio-800 text-studio-400"><component :is="service.icon" :size="16" /></span><div class="min-w-0 flex-1"><p class="text-xs font-medium">{{ service.label }}</p><p class="mt-1 truncate text-[10px] text-studio-400">{{ service.sub }}</p></div><Check v-if="health?.[service.key]" :size="15" class="text-lime-300" /><CircleAlert v-else :size="15" class="text-amber-200" /></div></div><p class="hint mt-5 border-t divider pt-4">Zugangsdaten und Endpoints werden über die <code class="text-zinc-300">.env</code>-Datei auf dem Server konfiguriert.</p></section>
        <section v-if="storageInfo" class="panel p-5"><h2 class="mb-5 text-sm font-semibold">Speicher im Überblick</h2><dl class="space-y-4 text-xs"><div class="flex justify-between"><dt class="text-studio-400">Clips in S3</dt><dd class="font-mono">{{ bytes(storageInfo.stored_bytes) }}</dd></div><div class="flex justify-between"><dt class="text-studio-400">Videopuffer</dt><dd class="font-mono">{{ bytes(storageInfo.buffer_bytes) }}</dd></div><div class="flex justify-between border-t divider pt-4"><dt class="text-studio-400">Lokal verfügbar</dt><dd class="font-mono text-lime-300">{{ bytes(storageInfo.disk_free_bytes) }}</dd></div></dl></section>
        <section class="rounded-xl border border-lime-300/15 bg-lime-300/3 p-5"><AudioLines :size="20" class="mb-3 text-lime-300" /><h3 class="text-sm font-medium">Auf jeden Kanal abgestimmt.</h3><p class="mt-2 text-xs leading-relaxed text-studio-400">Audio-Schwelle, Aufnahmequalität und Clip-Vor-/Nachlauf stellst du pro Streamer ein.</p><NuxtLink to="/streamers" class="mt-4 inline-block text-xs font-medium text-lime-300">Zur Watchlist →</NuxtLink></section>
        <p class="flex gap-2 px-1 text-[10px] leading-relaxed text-studio-400"><Info :size="13" class="mt-0.5 shrink-0" />Der Kernbetrieb verwendet die Stream-Auflösung von Streamlink. Eine eigene Twitch-Helix-Anbindung ist nicht erforderlich.</p>
      </div>
    </div>
  </div>
</template>
